package io.github.wxmyyds.discordautotranslate.ui;
import android.app.Activity;import android.app.AlertDialog;import android.app.Dialog;import android.content.res.ColorStateList;import android.content.res.TypedArray;import android.graphics.Color;import android.graphics.drawable.ColorDrawable;import android.graphics.drawable.GradientDrawable;import android.graphics.drawable.RippleDrawable;import android.view.View;import android.view.ViewGroup;import android.view.Window;import android.view.animation.DecelerateInterpolator;import android.widget.Button;import android.widget.EditText;import android.widget.LinearLayout;import android.widget.ScrollView;import android.widget.Spinner;import android.widget.Switch;import android.widget.TextView;
/** Shared adaptive visual system for settings screens and standard dialogs. */
final class SettingsUiStyle{
 private static final int[] ATTRS={android.R.attr.colorBackground,android.R.attr.textColorPrimary,android.R.attr.textColorSecondary,android.R.attr.colorAccent};
 private SettingsUiStyle(){}
 static void apply(Activity a,View v,View primary){Palette p=palette(a);v.setBackgroundColor(p.surface);tree(a,v,p,primary);if(v instanceof ScrollView){ScrollView s=(ScrollView)v;s.setFillViewport(true);s.setClipToPadding(false);s.setSmoothScrollingEnabled(true);s.setOverScrollMode(View.OVER_SCROLL_IF_CONTENT_SCROLLS);}animate(v);}
 static void styleDialog(Activity a,Dialog d){if(d==null||d.getWindow()==null)return;Palette p=palette(a);Window w=d.getWindow();w.setBackgroundDrawable(new ColorDrawable(p.surface));w.setWindowAnimations(android.R.style.Animation_Dialog);int width=Math.min(dp(a,560),Math.max(dp(a,280),a.getResources().getDisplayMetrics().widthPixels-dp(a,32)));w.setLayout(width,ViewGroup.LayoutParams.WRAP_CONTENT);tree(a,w.getDecorView(),p,null);animate(w.getDecorView());if(d instanceof AlertDialog){AlertDialog x=(AlertDialog)d;button(a,x.getButton(-1),p,true);button(a,x.getButton(-2),p,false);button(a,x.getButton(-3),p,false);}}
 static void styleFullscreenDialog(Activity a,Dialog d){if(d==null||d.getWindow()==null)return;Palette p=palette(a);Window w=d.getWindow();w.setBackgroundDrawable(new ColorDrawable(p.surface));tree(a,w.getDecorView(),p,null);animate(w.getDecorView());}
 private static void tree(Activity a,View v,Palette p,View primary){
  if(v instanceof Switch){Switch s=(Switch)v;s.setMinimumHeight(dp(a,48));s.setTextColor(p.text);s.setThumbTintList(new ColorStateList(new int[][]{{android.R.attr.state_checked},{}},new int[]{p.accent,p.secondary}));s.setTrackTintList(new ColorStateList(new int[][]{{android.R.attr.state_checked},{}},new int[]{alpha(p.accent,0x66),alpha(p.secondary,0x55)}));}
  else if(v instanceof Button)button(a,(Button)v,p,v==primary);
  else if(v instanceof EditText){EditText e=(EditText)v;e.setTextColor(p.text);e.setHintTextColor(p.secondary);e.setPadding(dp(a,14),dp(a,11),dp(a,14),dp(a,11));e.setMinHeight(dp(a,48));e.setBackground(ripple(p,shape(p.surface,p.outline,dp(a,1),dp(a,11))));}
  else if(v instanceof Spinner){Spinner s=(Spinner)v;s.setMinimumHeight(dp(a,48));s.setPadding(dp(a,10),0,dp(a,10),0);s.setBackground(ripple(p,shape(p.surface,p.outline,dp(a,1),dp(a,11))));}
  else if(v instanceof TextView){TextView t=(TextView)v;float size=t.getTextSize()/a.getResources().getDisplayMetrics().scaledDensity;t.setTextColor(size<=13.5f?p.secondary:p.text);t.setLineSpacing(dp(a,2),1f);if(size>=16)t.setTypeface(t.getTypeface(),android.graphics.Typeface.BOLD);}
  if(v instanceof LinearLayout){LinearLayout l=(LinearLayout)v;for(int i=0;i<l.getChildCount();i++){View c=l.getChildAt(i);if(c.getLayoutParams() instanceof LinearLayout.LayoutParams){LinearLayout.LayoutParams q=(LinearLayout.LayoutParams)c.getLayoutParams();int h=l.getOrientation()==0?dp(a,3):0,y=l.getOrientation()==1?dp(a,3):0;q.setMargins(q.leftMargin+h,q.topMargin+y,q.rightMargin+h,q.bottomMargin+y);c.setLayoutParams(q);}}}
  if(v instanceof ViewGroup){ViewGroup g=(ViewGroup)v;for(int i=0;i<g.getChildCount();i++)tree(a,g.getChildAt(i),p,primary);}
 }
 private static void button(Activity a,Button b,Palette p,boolean primary){if(b==null)return;b.setAllCaps(false);b.setTextSize(14);b.setMinimumHeight(dp(a,48));b.setPadding(dp(a,16),dp(a,9),dp(a,16),dp(a,9));b.setTextColor(primary?contrast(p.accent):p.accent);b.setBackground(ripple(p,shape(primary?p.accent:p.surface,primary?p.accent:p.outline,dp(a,1),dp(a,12))));b.setElevation(dp(a,primary?2:0));}
 private static GradientDrawable shape(int fill,int stroke,int sw,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(radius);if(sw>0)d.setStroke(sw,stroke);return d;}
 private static RippleDrawable ripple(Palette p,GradientDrawable d){return new RippleDrawable(ColorStateList.valueOf(alpha(p.accent,0x28)),d,null);}
 private static Palette palette(Activity a){TypedArray t=a.obtainStyledAttributes(ATTRS);try{int bg=t.getColor(0,Color.WHITE),fg=t.getColor(1,Color.BLACK),sec=t.getColor(2,0xff777777),accent=t.getColor(3,0xff5865f2);return new Palette(blend(bg,accent,.035f),fg,sec,accent,blend(bg,fg,.20f));}finally{t.recycle();}}
 private static int blend(int x,int y,float f){return Color.rgb(Math.round(Color.red(x)*(1-f)+Color.red(y)*f),Math.round(Color.green(x)*(1-f)+Color.green(y)*f),Math.round(Color.blue(x)*(1-f)+Color.blue(y)*f));}
 private static int alpha(int c,int a){return(c&0xffffff)|((a&255)<<24);}private static int contrast(int c){double l=(.2126*Color.red(c)+.7152*Color.green(c)+.0722*Color.blue(c))/255;return l>.58?Color.BLACK:Color.WHITE;}
 private static void animate(View v){v.setAlpha(0);v.setTranslationY(dp(v.getContext(),6));v.animate().alpha(1).translationY(0).setDuration(190).setInterpolator(new DecelerateInterpolator()).start();}
 private static int dp(Activity a,int v){return Math.round(v*a.getResources().getDisplayMetrics().density);}private static int dp(android.content.Context c,int v){return Math.round(v*c.getResources().getDisplayMetrics().density);}
 private static final class Palette{final int surface,text,secondary,accent,outline;Palette(int s,int t,int x,int a,int o){surface=s;text=t;secondary=x;accent=a;outline=o;}}
}